with open("input.txt", "r") as f:
 S = f.read().strip()
n = len(S)
results = []
for i in range(n - 2):
 sub = S[i:i+3]
 if sub[0].lower() == sub[1].lower() == sub[2].lower():
 results.append(f"{i+1}{sub}")
with open("output.txt", "w") as f:
 if results:
 f.write("\n".join(results))
 else:
 f.write("0")
